import React, { useState } from "react";

import {
  AppBar,
  Toolbar,
  Typography,
  Box,
  Button,
  Grid,
  Card,
  CardContent,
  Chip,
  Avatar,
  Paper,
  Divider,
  List,
  ListItem,
  ListItemText,
  ListItemIcon,
  Drawer,
  IconButton,
  useMediaQuery,
  useTheme,
} from "@mui/material";

import {
  Restaurant as RestaurantIcon,
  Dashboard as DashboardIcon,
  ShoppingCart as OrdersIcon,
  AccessTime as PendingIcon,
  LocalFireDepartment as PreparingIcon,
  CheckCircle as ReadyIcon,
  DoneAll as ServedIcon,
  Logout as LogoutIcon,
  Menu as MenuIcon,
  Kitchen as KitchenIcon,
} from "@mui/icons-material";

const drawerWidth = 230;

/* =========================================================
   DEMO ORDERS
========================================================= */

const initialOrders = [
  {
    id: "ORD-1001",
    customer: "Rahul",
    items: "Biryani × 1",
    amount: 180,
    status: "Pending",
    time: "2 min ago",
  },
  {
    id: "ORD-1002",
    customer: "Priya",
    items: "Masala Dosa × 2",
    amount: 160,
    status: "Preparing",
    time: "8 min ago",
  },
  {
    id: "ORD-1003",
    customer: "Kiran",
    items: "Burger × 1",
    amount: 150,
    status: "Ready",
    time: "12 min ago",
  },
];

/* =========================================================
   STAFF DASHBOARD
========================================================= */

const StaffDashboard = ({
  user,
  onLogout,
}) => {
  const theme = useTheme();

  const isMobile = useMediaQuery(
    theme.breakpoints.down("md")
  );

  const [mobileOpen, setMobileOpen] =
    useState(false);

  const [activePage, setActivePage] =
    useState("Dashboard");

  const [orders, setOrders] =
    useState(initialOrders);

  /* =======================================================
     NAVIGATION
  ======================================================= */

  const navigationItems = [
    {
      name: "Dashboard",
      icon: <DashboardIcon />,
    },
    {
      name: "New Orders",
      icon: <PendingIcon />,
    },
    {
      name: "Preparing",
      icon: <PreparingIcon />,
    },
    {
      name: "Ready",
      icon: <ReadyIcon />,
    },
    {
      name: "Served",
      icon: <ServedIcon />,
    },
  ];

  const handleNavigation = (
    page
  ) => {
    setActivePage(page);

    if (isMobile) {
      setMobileOpen(false);
    }
  };

  /* =======================================================
     STATUS UPDATE
  ======================================================= */

  const updateOrderStatus = (
    orderId,
    newStatus
  ) => {
    setOrders((previousOrders) =>
      previousOrders.map((order) =>
        order.id === orderId
          ? {
            ...order,
            status: newStatus,
          }
          : order
      )
    );
  };

  /* =======================================================
     STATUS COLORS
  ======================================================= */

  const getStatusColor = (
    status
  ) => {
    if (status === "Pending")
      return "warning";

    if (status === "Preparing")
      return "info";

    if (status === "Ready")
      return "secondary";

    if (status === "Served")
      return "success";

    return "default";
  };

  /* =======================================================
     DRAWER
  ======================================================= */

  const drawerContent = (
    <Box
      sx={{
        height: "100%",
        display: "flex",
        flexDirection: "column",
      }}
    >
      {/* Logo */}

      <Box
        sx={{
          p: 2.5,
          display: "flex",
          alignItems: "center",
          gap: 1.5,
          background:
            "linear-gradient(135deg, #2E7D32, #4CAF50)",
          color: "white",
        }}
      >
        <KitchenIcon
          sx={{ fontSize: 34 }}
        />

        <Box>
          <Typography
            variant="h6"
            sx={{ fontWeight: 800 }}
          >
            CanteenPro
          </Typography>

          <Typography
            variant="caption"
            sx={{ opacity: 0.9 }}
          >
            Staff Kitchen
          </Typography>
        </Box>
      </Box>

      {/* Navigation */}

      <List
        sx={{
          p: 1.5,
          flexGrow: 1,
        }}
      >
        {navigationItems.map(
          (item) => {
            const selected =
              activePage === item.name;

            return (
              <ListItem
                key={item.name}
                disablePadding
                sx={{ mb: 0.5 }}
              >
                <Button
                  fullWidth
                  startIcon={item.icon}
                  onClick={() =>
                    handleNavigation(
                      item.name
                    )
                  }
                  sx={{
                    justifyContent:
                      "flex-start",
                    textTransform:
                      "none",
                    px: 2,
                    py: 1.3,
                    borderRadius: 2,
                    color: selected
                      ? "#2E7D32"
                      : "#555",
                    backgroundColor:
                      selected
                        ? "#E8F5E9"
                        : "transparent",
                    fontWeight: selected
                      ? 700
                      : 500,

                    "&:hover": {
                      backgroundColor:
                        "#E8F5E9",
                      color: "#2E7D32",
                    },
                  }}
                >
                  {item.name}
                </Button>
              </ListItem>
            );
          }
        )}
      </List>

      <Divider />

      {/* Logout */}

      <Box sx={{ p: 2 }}>
        <Button
          fullWidth
          variant="outlined"
          color="error"
          startIcon={
            <LogoutIcon />
          }
          onClick={onLogout}
          sx={{
            textTransform:
              "none",
            fontWeight: 700,
            borderRadius: 2,
            py: 1.2,
          }}
        >
          Logout
        </Button>
      </Box>
    </Box>
  );

  /* =======================================================
     ORDER CARD
  ======================================================= */

  const OrderCard = ({ order }) => {
    return (
      <Card
        sx={{
          borderRadius: 3,
          height: "100%",
        }}
      >
        <CardContent>
          <Box
            sx={{
              display: "flex",
              justifyContent:
                "space-between",
              alignItems:
                "flex-start",
              mb: 2,
            }}
          >
            <Box>
              <Typography
                variant="h6"
                sx={{
                  fontWeight: 800,
                }}
              >
                {order.id}
              </Typography>

              <Typography
                variant="body2"
                color="text.secondary"
              >
                {order.time}
              </Typography>
            </Box>

            <Chip
              label={order.status}
              color={getStatusColor(
                order.status
              )}
              size="small"
              sx={{
                fontWeight: 700,
              }}
            />
          </Box>

          <Divider sx={{ mb: 2 }} />

          <Typography
            variant="body1"
            sx={{
              fontWeight: 700,
            }}
          >
            Customer
          </Typography>

          <Typography
            color="text.secondary"
            sx={{ mb: 2 }}
          >
            {order.customer}
          </Typography>

          <Typography
            variant="body1"
            sx={{
              fontWeight: 700,
            }}
          >
            Items
          </Typography>

          <Typography
            color="text.secondary"
            sx={{ mb: 2 }}
          >
            {order.items}
          </Typography>

          <Typography
            variant="h6"
            color="primary"
            sx={{
              fontWeight: 800,
              mb: 2,
            }}
          >
            ₹{order.amount}
          </Typography>

          {/* Action buttons */}

          {order.status ===
            "Pending" && (
              <Button
                fullWidth
                variant="contained"
                color="warning"
                startIcon={
                  <PreparingIcon />
                }
                onClick={() =>
                  updateOrderStatus(
                    order.id,
                    "Preparing"
                  )
                }
                sx={{
                  borderRadius: 2,
                  fontWeight: 700,
                  textTransform:
                    "none",
                }}
              >
                Start Preparing
              </Button>
            )}

          {order.status ===
            "Preparing" && (
              <Button
                fullWidth
                variant="contained"
                color="secondary"
                startIcon={
                  <ReadyIcon />
                }
                onClick={() =>
                  updateOrderStatus(
                    order.id,
                    "Ready"
                  )
                }
                sx={{
                  borderRadius: 2,
                  fontWeight: 700,
                  textTransform:
                    "none",
                }}
              >
                Mark Ready
              </Button>
            )}

          {order.status ===
            "Ready" && (
              <Button
                fullWidth
                variant="contained"
                color="success"
                startIcon={
                  <ServedIcon />
                }
                onClick={() =>
                  updateOrderStatus(
                    order.id,
                    "Served"
                  )
                }
                sx={{
                  borderRadius: 2,
                  fontWeight: 700,
                  textTransform:
                    "none",
                }}
              >
                Mark Served
              </Button>
            )}

          {order.status ===
            "Served" && (
              <Button
                fullWidth
                variant="outlined"
                color="success"
                disabled
                sx={{
                  borderRadius: 2,
                  fontWeight: 700,
                  textTransform:
                    "none",
                }}
              >
                Order Completed
              </Button>
            )}
        </CardContent>
      </Card>
    );
  };

  /* =======================================================
     DASHBOARD
  ======================================================= */

  const renderDashboard =
    () => {
      const pending = orders.filter(
        (order) =>
          order.status ===
          "Pending"
      ).length;

      const preparing =
        orders.filter(
          (order) =>
            order.status ===
            "Preparing"
        ).length;

      const ready = orders.filter(
        (order) =>
          order.status ===
          "Ready"
      ).length;

      const served = orders.filter(
        (order) =>
          order.status ===
          "Served"
      ).length;

      return (
        <>
          {/* Welcome */}

          <Paper
            sx={{
              p: 3,
              mb: 3,
              borderRadius: 3,
              background:
                "linear-gradient(135deg, #2E7D32, #4CAF50)",
              color: "white",
            }}
          >
            <Typography
              variant="h4"
              sx={{
                fontWeight: 800,
              }}
            >
              Welcome, {user.name}
            </Typography>

            <Typography
              sx={{
                mt: 1,
                opacity: 0.9,
              }}
            >
              Manage customer orders
              and kitchen preparation.
            </Typography>

            <Typography
              variant="body2"
              sx={{
                mt: 1,
                opacity: 0.85,
              }}
            >
              Mobile:{" "}
              {user.mobile}
            </Typography>
          </Paper>

          {/* Statistics */}

          <Grid
            container
            spacing={2.5}
            sx={{ mb: 3 }}
          >
            <Grid
              item
              xs={12}
              sm={6}
              md={3}
            >
              <Card
                sx={{
                  borderRadius: 3,
                }}
              >
                <CardContent>
                  <Avatar
                    sx={{
                      bgcolor:
                        "#FFF3E0",
                      color:
                        "#EF6C00",
                      mb: 2,
                    }}
                  >
                    <PendingIcon />
                  </Avatar>

                  <Typography
                    color="text.secondary"
                  >
                    Pending
                  </Typography>

                  <Typography
                    variant="h4"
                    sx={{
                      fontWeight: 800,
                    }}
                  >
                    {pending}
                  </Typography>
                </CardContent>
              </Card>
            </Grid>

            <Grid
              item
              xs={12}
              sm={6}
              md={3}
            >
              <Card
                sx={{
                  borderRadius: 3,
                }}
              >
                <CardContent>
                  <Avatar
                    sx={{
                      bgcolor:
                        "#E3F2FD",
                      color:
                        "#1976D2",
                      mb: 2,
                    }}
                  >
                    <PreparingIcon />
                  </Avatar>

                  <Typography
                    color="text.secondary"
                  >
                    Preparing
                  </Typography>

                  <Typography
                    variant="h4"
                    sx={{
                      fontWeight: 800,
                    }}
                  >
                    {preparing}
                  </Typography>
                </CardContent>
              </Card>
            </Grid>

            <Grid
              item
              xs={12}
              sm={6}
              md={3}
            >
              <Card
                sx={{
                  borderRadius: 3,
                }}
              >
                <CardContent>
                  <Avatar
                    sx={{
                      bgcolor:
                        "#F3E5F5",
                      color:
                        "#7B1FA2",
                      mb: 2,
                    }}
                  >
                    <ReadyIcon />
                  </Avatar>

                  <Typography
                    color="text.secondary"
                  >
                    Ready
                  </Typography>

                  <Typography
                    variant="h4"
                    sx={{
                      fontWeight: 800,
                    }}
                  >
                    {ready}
                  </Typography>
                </CardContent>
              </Card>
            </Grid>

            <Grid
              item
              xs={12}
              sm={6}
              md={3}
            >
              <Card
                sx={{
                  borderRadius: 3,
                }}
              >
                <CardContent>
                  <Avatar
                    sx={{
                      bgcolor:
                        "#E8F5E9",
                      color:
                        "#2E7D32",
                      mb: 2,
                    }}
                  >
                    <ServedIcon />
                  </Avatar>

                  <Typography
                    color="text.secondary"
                  >
                    Served
                  </Typography>

                  <Typography
                    variant="h4"
                    sx={{
                      fontWeight: 800,
                    }}
                  >
                    {served}
                  </Typography>
                </CardContent>
              </Card>
            </Grid>
          </Grid>

          {/* Orders */}

          <Paper
            sx={{
              p: 3,
              borderRadius: 3,
            }}
          >
            <Box
              sx={{
                display: "flex",
                alignItems:
                  "center",
                gap: 1,
                mb: 2,
              }}
            >
              <OrdersIcon
                sx={{
                  color:
                    "#2E7D32",
                }}
              />

              <Typography
                variant="h6"
                sx={{
                  fontWeight: 800,
                }}
              >
                Current Orders
              </Typography>
            </Box>

            <Divider sx={{ mb: 3 }} />

            <Grid
              container
              spacing={2.5}
            >
              {orders.map(
                (order) => (
                  <Grid
                    item
                    xs={12}
                    md={6}
                    lg={4}
                    key={order.id}
                  >
                    <OrderCard
                      order={order}
                    />
                  </Grid>
                )
              )}
            </Grid>
          </Paper>
        </>
      );
    };

  /* =======================================================
     FILTERED ORDERS PAGE
  ======================================================= */

  const renderOrdersByStatus =
    (status) => {
      const filteredOrders =
        orders.filter(
          (order) =>
            order.status ===
            status
        );

      return (
        <Paper
          sx={{
            p: 3,
            borderRadius: 3,
          }}
        >
          <Typography
            variant="h4"
            sx={{
              fontWeight: 800,
              color: "#2E7D32",
              mb: 3,
            }}
          >
            {status} Orders
          </Typography>

          <Grid
            container
            spacing={2.5}
          >
            {filteredOrders.length >
              0 ? (
              filteredOrders.map(
                (order) => (
                  <Grid
                    item
                    xs={12}
                    md={6}
                    lg={4}
                    key={order.id}
                  >
                    <OrderCard
                      order={order}
                    />
                  </Grid>
                )
              )
            ) : (
              <Grid item xs={12}>
                <Box
                  sx={{
                    textAlign:
                      "center",
                    py: 6,
                  }}
                >
                  <OrdersIcon
                    sx={{
                      fontSize: 60,
                      color:
                        "#BDBDBD",
                    }}
                  />

                  <Typography
                    variant="h6"
                    color="text.secondary"
                  >
                    No {status.toLowerCase()}{" "}
                    orders.
                  </Typography>
                </Box>
              </Grid>
            )}
          </Grid>
        </Paper>
      );
    };

  /* =======================================================
     MAIN UI
  ======================================================= */

  return (
    <Box
      sx={{
        display: "flex",
        minHeight: "100vh",
        backgroundColor:
          "#F5F7F5",
      }}
    >
      {/* Desktop Drawer */}

      {!isMobile && (
        <Drawer
          variant="permanent"
          sx={{
            width:
              drawerWidth,
            flexShrink: 0,

            "& .MuiDrawer-paper":
            {
              width:
                drawerWidth,
              boxSizing:
                "border-box",
              borderRight:
                "1px solid #E0E0E0",
            },
          }}
        >
          {drawerContent}
        </Drawer>
      )}

      {/* Mobile Drawer */}

      {isMobile && (
        <Drawer
          variant="temporary"
          open={mobileOpen}
          onClose={() =>
            setMobileOpen(false)
          }
          sx={{
            "& .MuiDrawer-paper":
            {
              width:
                drawerWidth,
            },
          }}
        >
          {drawerContent}
        </Drawer>
      )}

      {/* Main */}

      <Box
        sx={{
          flexGrow: 1,
          minWidth: 0,
        }}
      >
        {/* Header */}

        <AppBar
          position="sticky"
          elevation={0}
          sx={{
            backgroundColor:
              "white",
            color: "#222",
            borderBottom:
              "1px solid #E0E0E0",
          }}
        >
          <Toolbar>
            {isMobile && (
              <IconButton
                onClick={() =>
                  setMobileOpen(
                    true
                  )
                }
                sx={{ mr: 2 }}
              >
                <MenuIcon />
              </IconButton>
            )}

            <Typography
              variant="h6"
              sx={{
                flexGrow: 1,
                fontWeight: 800,
                color:
                  "#2E7D32",
              }}
            >
              {activePage}
            </Typography>

            <Avatar
              sx={{
                bgcolor:
                  "#2E7D32",
                fontWeight: 700,
              }}
            >
              {user.name
                ? user.name
                  .charAt(0)
                  .toUpperCase()
                : "S"}
            </Avatar>
          </Toolbar>
        </AppBar>

        {/* Content */}

        <Box
          sx={{
            p: {
              xs: 2,
              sm: 3,
              md: 4,
            },
          }}
        >
          {activePage ===
            "Dashboard" &&
            renderDashboard()}

          {activePage ===
            "New Orders" &&
            renderOrdersByStatus(
              "Pending"
            )}

          {activePage ===
            "Preparing" &&
            renderOrdersByStatus(
              "Preparing"
            )}

          {activePage ===
            "Ready" &&
            renderOrdersByStatus(
              "Ready"
            )}

          {activePage ===
            "Served" &&
            renderOrdersByStatus(
              "Served"
            )}
        </Box>
      </Box>
    </Box>
  );
};

export default StaffDashboard;
